using MongoDB.Bson;
using MongoDB.Driver;
using VirGo.Application.Marketplace;
using VirGo.Domain.Payments;

namespace VirGo.Infrastructure;

public sealed class InMemoryPaymentCardRepository : IPaymentCardRepository
{
    private readonly List<PaymentCard> cards = [];
    private readonly Lock gate = new();
    public Task<IReadOnlyList<PaymentCard>> ListAsync(string userId, CancellationToken cancellationToken = default) { cancellationToken.ThrowIfCancellationRequested(); lock (gate) return Task.FromResult<IReadOnlyList<PaymentCard>>(cards.Where(card => card.UserId == userId).ToArray()); }
    public Task<PaymentCard?> AddAsync(PaymentCard card, CancellationToken cancellationToken = default) { cancellationToken.ThrowIfCancellationRequested(); lock (gate) { if (cards.Any(item => item.UserId == card.UserId && item.GatewayToken == card.GatewayToken)) return Task.FromResult<PaymentCard?>(null); if (card.IsDefault || !cards.Any(item => item.UserId == card.UserId)) SetDefaults(card.UserId); cards.Add(card); return Task.FromResult<PaymentCard?>(card); } }
    public Task<PaymentCard?> UpdateAsync(PaymentCard card, CancellationToken cancellationToken = default) { cancellationToken.ThrowIfCancellationRequested(); lock (gate) { var index = cards.FindIndex(item => item.Id == card.Id && item.UserId == card.UserId); if (index < 0) return Task.FromResult<PaymentCard?>(null); cards[index] = card; return Task.FromResult<PaymentCard?>(card); } }
    public Task<bool> DeleteAsync(string userId, string id, CancellationToken cancellationToken = default) { cancellationToken.ThrowIfCancellationRequested(); lock (gate) return Task.FromResult(cards.RemoveAll(card => card.Id == id && card.UserId == userId) > 0); }
    public Task<PaymentCard?> SetDefaultAsync(string userId, string id, CancellationToken cancellationToken = default) { cancellationToken.ThrowIfCancellationRequested(); lock (gate) { var card = cards.FirstOrDefault(item => item.Id == id && item.UserId == userId); if (card is null) return Task.FromResult<PaymentCard?>(null); SetDefaults(userId); var updated = new PaymentCard { Id = card.Id, UserId = card.UserId, Brand = card.Brand, Last4 = card.Last4, ExpMonth = card.ExpMonth, ExpYear = card.ExpYear, GatewayToken = card.GatewayToken, IsDefault = true }; cards[cards.FindIndex(item => item.Id == id)] = updated; return Task.FromResult<PaymentCard?>(updated); } }
    private void SetDefaults(string userId) { for (var i = 0; i < cards.Count; i++) if (cards[i].UserId == userId) cards[i] = new PaymentCard { Id = cards[i].Id, UserId = cards[i].UserId, Brand = cards[i].Brand, Last4 = cards[i].Last4, ExpMonth = cards[i].ExpMonth, ExpYear = cards[i].ExpYear, GatewayToken = cards[i].GatewayToken, IsDefault = false }; }
}

public sealed class MongoPaymentCardRepository(IMongoDatabase database) : IPaymentCardRepository
{
    private readonly IMongoCollection<BsonDocument> cards = database.GetCollection<BsonDocument>("paymentCards");
    public async Task<IReadOnlyList<PaymentCard>> ListAsync(string userId, CancellationToken cancellationToken = default) => (await cards.Find(Builders<BsonDocument>.Filter.Eq("userId", userId)).ToListAsync(cancellationToken)).Select(Map).ToArray();
    public async Task<PaymentCard?> AddAsync(PaymentCard card, CancellationToken cancellationToken = default) { if (await cards.Find(Builders<BsonDocument>.Filter.And(Builders<BsonDocument>.Filter.Eq("userId", card.UserId), Builders<BsonDocument>.Filter.Eq("gatewayToken", card.GatewayToken))).AnyAsync(cancellationToken)) return null; if (card.IsDefault) await cards.UpdateManyAsync(Builders<BsonDocument>.Filter.Eq("userId", card.UserId), Builders<BsonDocument>.Update.Set("isDefault", false), cancellationToken: cancellationToken); await cards.InsertOneAsync(new BsonDocument { ["_id"] = card.Id, ["userId"] = card.UserId, ["brand"] = card.Brand, ["last4"] = card.Last4, ["expMonth"] = card.ExpMonth, ["expYear"] = card.ExpYear, ["gatewayToken"] = card.GatewayToken, ["isDefault"] = card.IsDefault }, cancellationToken: cancellationToken); return card; }
    public async Task<PaymentCard?> UpdateAsync(PaymentCard card, CancellationToken cancellationToken = default) { var document = await cards.FindOneAndUpdateAsync(Builders<BsonDocument>.Filter.And(Builders<BsonDocument>.Filter.Eq("_id", card.Id), Builders<BsonDocument>.Filter.Eq("userId", card.UserId)), Builders<BsonDocument>.Update.Set("brand", card.Brand).Set("last4", card.Last4).Set("expMonth", card.ExpMonth).Set("expYear", card.ExpYear).Set("isDefault", card.IsDefault), new FindOneAndUpdateOptions<BsonDocument> { ReturnDocument = ReturnDocument.After }, cancellationToken); return document is null ? null : Map(document); }
    public async Task<bool> DeleteAsync(string userId, string id, CancellationToken cancellationToken = default) => (await cards.DeleteOneAsync(Builders<BsonDocument>.Filter.And(Builders<BsonDocument>.Filter.Eq("_id", id), Builders<BsonDocument>.Filter.Eq("userId", userId)), cancellationToken)).DeletedCount > 0;
    public async Task<PaymentCard?> SetDefaultAsync(string userId, string id, CancellationToken cancellationToken = default) { await cards.UpdateManyAsync(Builders<BsonDocument>.Filter.Eq("userId", userId), Builders<BsonDocument>.Update.Set("isDefault", false), cancellationToken: cancellationToken); var document = await cards.FindOneAndUpdateAsync(Builders<BsonDocument>.Filter.And(Builders<BsonDocument>.Filter.Eq("_id", id), Builders<BsonDocument>.Filter.Eq("userId", userId)), Builders<BsonDocument>.Update.Set("isDefault", true), new FindOneAndUpdateOptions<BsonDocument> { ReturnDocument = ReturnDocument.After }, cancellationToken); return document is null ? null : Map(document); }
    private static PaymentCard Map(BsonDocument d) => new() { Id = d.GetValue("_id").AsString, UserId = d.GetValue("userId").AsString, Brand = d.GetValue("brand").AsString, Last4 = d.GetValue("last4").AsString, ExpMonth = d.GetValue("expMonth").ToInt32(), ExpYear = d.GetValue("expYear").ToInt32(), GatewayToken = d.GetValue("gatewayToken").AsString, IsDefault = d.GetValue("isDefault").AsBoolean };
}
